package com.example.campusmaintenance.dto;
import com.example.campusmaintenance.enums.*; import jakarta.validation.constraints.*;
public class MaintenanceRequestDto { @NotBlank @Size(min=3,max=100) private String title; @NotBlank @Size(min=10,max=1000) private String description; @NotNull private Category category; @NotNull private Priority priority; @NotBlank @Size(min=2,max=100) private String studentName; @NotBlank @Size(min=1,max=30) private String room;
public MaintenanceRequestDto(){} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public Category getCategory(){return category;} public void setCategory(Category v){category=v;} public Priority getPriority(){return priority;} public void setPriority(Priority v){priority=v;} public String getStudentName(){return studentName;} public void setStudentName(String v){studentName=v;} public String getRoom(){return room;} public void setRoom(String v){room=v;}}
